/**
 * The app entity's locals.tf contribution, in ei's exact shapes:
 * `<ns>_stage_ids_by_key`, the ten `<ns>_*_field_id` system lookups, and
 * `<ns>_status_options_by_label` / `<ns>_stage_options_by_label`
 * for-expressions (loop variables `opt` / `s`, matching ei's emitter
 * verbatim). Field-level lookups are the field entity's contribution
 * (entities/field/locals.ts).
 */
import { expr } from "../../engine/tf/index.js";
import { APP_RESOURCE_TYPE } from "./module.js";
const SYSTEM_FIELD_ID_ATTRS = [
    "title_field_id",
    "status_field_id",
    "stage_field_id",
    "id_field_id",
    "created_by_field_id",
    "created_at_field_id",
    "updated_by_field_id",
    "updated_at_field_id",
    "closed_by_field_id",
    "closed_at_field_id",
];
/** Append one app's system lookup locals, keyed by its namespace (= tfLabel). */
export function appendAppLocals(attrs, ns) {
    const app = (path) => expr.resourceAttr(APP_RESOURCE_TYPE, ns, [path]);
    attrs[`${ns}_stage_ids_by_key`] = app("stage_ids_by_key");
    for (const attr of SYSTEM_FIELD_ID_ATTRS)
        attrs[`${ns}_${attr}`] = app(attr);
    attrs[`${ns}_status_options_by_label`] = expr.forObject("opt", app("status_options"), expr.scopedAttr("opt", ["label"]), expr.scopedAttr("opt", ["id"]));
    attrs[`${ns}_stage_options_by_label`] = expr.forObject("s", app("stages"), expr.scopedAttr("s", ["name"]), expr.scopedAttr("s", ["id"]));
}
